8153: # (wave 26c, D3 / F26-3, F25-1) The tool calls in flight in an engine's event stream, updated per
8154: # complete line ($Open: a HashSet[string] of their keys): codex `item.started` of a
8155: # command_execution, mcp_tool_call or web_search item until its `item.completed` (by the item id;
8156: # an id-less one by its type); agy a `tool` step in state ACTIVE until the same step reports
8157: # another state; muse a task proposed with task_kind tool.* until its task.lifecycle end
8158: # (completed, failed, cancelled, rejected). A line that is not such an event changes nothing.
8159: $script:CodexToolItems = @('command_execution', 'mcp_tool_call', 'web_search')
8160: function Update-ToolFlight {
8161:     param([string]$Engine, [string]$Line, $Open)
8162:     $t = ([string]$Line).Trim()
8163:     if (-not $t.StartsWith('{')) { return }
8164:     # a cheap test first: most lines are messages and deltas
8165:     $isCodex = (-not $Engine -or $Engine -eq 'codex')
8166:     if ($isCodex -and $t.IndexOf('command_execution') -lt 0 -and $t.IndexOf('mcp_tool_call') -lt 0 -and $t.IndexOf('web_search') -lt 0) { return }
8167:     if ($Engine -eq 'agy' -and $t.IndexOf('"tool"') -lt 0) { return }
8168:     if ($Engine -eq 'muse' -and $t.IndexOf('task.lifecycle.') -lt 0) { return }
8169:     $obj = $null
8170:     try { $obj = ConvertFrom-Json -InputObject $t } catch { return }
8171:     if ($isCodex) {
8172:         $type = [string](Get-PropertyValue $obj 'type' '')
8173:         if ($type -ne 'item.started' -and $type -ne 'item.completed') { return }
8174:         $it = Get-PropertyValue $obj 'item' $null
8175:         if (-not (Test-IsJsonObject $it)) { return }
8176:         $itype = [string](Get-PropertyValue $it 'type' '')
8177:         if ($script:CodexToolItems -notcontains $itype) { return }
8178:         $id = [string](Get-PropertyValue $it 'id' '')
8179:         if ($type -eq 'item.started') { [void]$Open.Add($(if ($id) { "codex:$id" } else { "codex-type:$itype#$($Open.Count)" })); return }
8180:         if ($id -and $Open.Contains("codex:$id")) { [void]$Open.Remove("codex:$id"); return }
8181:         $k = @($Open | Where-Object { $_ -like "codex-type:$itype#*" }) | Select-Object -First 1
8182:         if ($k) { [void]$Open.Remove([string]$k) }
8183:         return
8184:     }
8185:     if ($Engine -eq 'agy') {
8186:         if ([string](Get-PropertyValue $obj 'event' '') -ne 'step_update') { return }
8187:         $su = Get-PropertyValue $obj 'step_update' $null
8188:         if (-not (Test-IsJsonObject $su) -or [string](Get-PropertyValue $su 'step_type' '') -ne 'tool') { return }
8189:         $key = "agy:$([string](Get-PropertyValue $su 'step_index' ''))"
8190:         if ([string](Get-PropertyValue $su 'state' '') -eq 'ACTIVE') { [void]$Open.Add($key) } else { [void]$Open.Remove($key) }
8191:         return
8192:     }
8193:     if ($Engine -eq 'muse') {
8194:         $pType = [string](Get-PropertyValue $obj 'payload_type' '')
8195:         if ($pType -notlike 'task.lifecycle.*') { return }
8196:         $payload = Get-PropertyValue $obj 'payload' $null
8197:         $ev = Get-PropertyValue $payload 'event' $null
8198:         $tid = [string](Get-PropertyValue $ev 'task_id' '')
8199:         if (-not $tid) { $tid = [string](Get-PropertyValue $payload 'task_id' '') }
8200:         if (-not $tid) { return }
8201:         if ($pType -eq 'task.lifecycle.proposed') {
8202:             if ([string](Get-PropertyValue $ev 'task_kind' '') -like 'tool.*') { [void]$Open.Add("muse:$tid") }
8203:             return
8204:         }
8205:         if (@('task.lifecycle.completed', 'task.lifecycle.failed', 'task.lifecycle.cancelled', 'task.lifecycle.canceled', 'task.lifecycle.rejected') -contains $pType) { [void]$Open.Remove("muse:$tid") }
8206:     }
8207: }
