8209: # (wave 26b, D10, D12) Waits for an engine turn's process: its wall-clock limit ($TimeoutSec), the
8210: # stall cut ($StallSec > 0: no output appended to $EventsPath for that long while the process
8211: # lives - the codex --json items, agy's stream-json, muse's MSP records all go to that file; the
8212: # clock starts with the turn) and the operator's kick ($KickPath appears).
8213: # (wave 26c, D3) The silent timer resets on ANY growth of the stream (bytes, not complete lines)
8214: # and is SUSPENDED while a tool call is in flight (Update-ToolFlight over $Engine's events): a
8215: # member running one long command is never cut; the timeout stays the hard bound.
8216: # (wave 26c, D1) The kick file is checked before the wait loop, on every poll and ONCE MORE after
8217: # the process exited: a kick found then is taken as LATE (KickLate - the outcome stays); every
8218: # taken kick is acknowledged (Confirm-Kick).
8219: # Polls every second (TEST HOOK: CODEX_CONSULT_TEST_WAIT_TICK_MS). Kills nothing - the caller
8220: # stops the tree. { Exited; Reason ('' | 'timeout' | 'stall' | 'kick'); KickLate; Events (lines
8221: # seen); LastEvent (DateTimeOffset of the last line seen, $null when none); Silent (seconds
8222: # without output outside a tool call at the stall cut); ToolWait (seconds the timer was suspended
8223: # for tool calls) }.
8224: function Wait-EngineProcess {
8225:     param($Process, [int]$TimeoutSec, [int]$StallSec = 0, [string]$EventsPath = '', [string]$KickPath = '', [string]$Engine = 'codex')
8226:     $r = [pscustomobject]@{ Exited = $false; Reason = ''; KickLate = $false; Events = 0; LastEvent = $null; Silent = 0; ToolWait = 0 }
8227:     $tick = 1000
8228:     $hook = 0
8229:     if ([int]::TryParse([string]$env:CODEX_CONSULT_TEST_WAIT_TICK_MS, [ref]$hook) -and $hook -gt 0) { $tick = $hook }
8230:     $watch = [System.Diagnostics.Stopwatch]::StartNew()

8230:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
8231:     $limitMs = [long]$TimeoutSec * 1000
8232:     $stallMs = [long]$StallSec * 1000
8233:     $offset = [long]0
8234:     $carry = [byte[]]@()
8235:     $lastMs = [long]0
8236:     $toolMs = [long]0
8237:     $open = New-Object 'System.Collections.Generic.HashSet[string]'
8238:     # before the loop: a kick for a turn still running stops it (one for a turn that has already
8239:     # exited is taken as late right below)
8240:     $exitedAlready = $false
8241:     try { $exitedAlready = [bool]$Process.HasExited } catch { }
8242:     if ($KickPath -and -not $exitedAlready -and [IO.File]::Exists($KickPath)) { $r.Reason = 'kick'; Confirm-Kick -KickPath $KickPath -What 'kicked'; return $r }
8243:     while ($true) {
8244:         $left = $limitMs - $watch.ElapsedMilliseconds
8245:         if ($left -le 0) { $r.Reason = 'timeout'; break }
8246:         if ($Process.WaitForExit([int][Math]::Min([long]$tick, $left))) {
8247:             $r.Exited = $true
8248:             if ($KickPath -and [IO.File]::Exists($KickPath)) { $r.KickLate = $true; Confirm-Kick -KickPath $KickPath -What 'late' }
8249:             break
8250:         }
8251:         if ($KickPath -and [IO.File]::Exists($KickPath)) { $r.Reason = 'kick'; Confirm-Kick -KickPath $KickPath -What 'kicked'; break }
8252:         if ($stallMs -gt 0 -and $EventsPath) {
8253:             $nowMs = $watch.ElapsedMilliseconds
8254:             $g = Read-StreamChunk -Path $EventsPath -Offset $offset -Carry $carry
8255:             $offset = $g.Offset
8256:             $carry = $g.Carry
8257:             if ($g.Bytes -gt 0) { $lastMs = $nowMs }
8258:             if (@($g.Lines).Count -gt 0) { $r.Events += @($g.Lines).Count; $r.LastEvent = [DateTimeOffset]::Now }
8259:             $wasOpen = ($open.Count -gt 0)
8260:             foreach ($ln in $g.Lines) { Update-ToolFlight -Engine $Engine -Line $ln -Open $open }
8261:             if ($wasOpen -or $open.Count -gt 0) {
8262:                 # a tool call in flight (or one that just ended): the silent timer does not run
8263:                 $toolMs += [Math]::Max([long]0, $nowMs - $lastMs)
8264:                 $lastMs = $nowMs
8265:                 continue
8266:             }
8267:             if (($nowMs - $lastMs) -ge $stallMs) {
8268:                 $r.Reason = 'stall'
8269:                 $r.Silent = [int][Math]::Floor(($nowMs - $lastMs) / 1000)
8270:                 break
8271:             }
8272:         }
8273:     }
8274:     $r.ToolWait = [int][Math]::Floor($toolMs / 1000)
8275:     return $r
8276: }
