8278: # Kills the process AND its descendants (the launcher is usually a shim: cmd.exe or
8279: # node in front of the real codex binary). Windows: taskkill /T /F; elsewhere: the
8280: # pgrep -P tree. Best effort; returns the pids (root included) still alive after it,
8281: # as an [int[]] (empty when the whole tree is gone).
8282: # A kill returns before the OS has torn the process down: the killed pids are polled
8283: # (100 ms steps, up to 3 s) and only those still alive after that wait are survivors.
8284: # A process merely still exiting must not be recorded as a survivor - that would keep
8285: # .consult.pending.json in state 'survivors' and block the task until a later run.
8286: function Stop-ProcessTree {
8287:     param($Process)
8288:     if ($null -eq $Process) { return , ([int[]]@()) }
8289:     $rootId = $Process.Id
8290:     $descendants = Get-DescendantPids -RootId $rootId
8291:     $previous = $ErrorActionPreference
8292:     $ErrorActionPreference = 'Continue'
8293:     try {
8294:         if ($script:OnWindows) {
8295:             try { & taskkill.exe /PID $rootId /T /F 2>$null | Out-Null } catch { }
8296:         }
8297:         # The root before its descendants: a root that outlives its children reacts to
8298:         # their death (a shell or node shim carries on and may start new processes).
8299:         try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
8300:         foreach ($d in $descendants) {
8301:             try { Stop-Process -Id $d -Force -ErrorAction SilentlyContinue } catch { }
8302:         }
8303:         try { $null = $Process.WaitForExit(10000) } catch { }
8304:     } finally {
8305:         $ErrorActionPreference = $previous
8306:     }
8307:     # Get-Process by pid is the liveness probe on every platform (kill -0 semantics).
8308:     $deadline = [DateTime]::UtcNow.AddSeconds(3)
8309:     while ($true) {
8310:         $alive = New-Object System.Collections.Generic.List[int]
8311:         $rootGone = $true
8312:         try { $rootGone = $Process.HasExited } catch { $rootGone = $true }
8313:         if (-not $rootGone) { $alive.Add($rootId) }
8314:         foreach ($d in $descendants) {
8315:             if (Get-Process -Id $d -ErrorAction SilentlyContinue) { $alive.Add($d) }
8316:         }
8317:         if ($alive.Count -eq 0 -or [DateTime]::UtcNow -ge $deadline) { break }
8318:         Start-Sleep -Milliseconds 100
8319:     }
8320:     return , ([int[]]$alive.ToArray())
8321: }
