6403: # A uniform in [0, 1) from 8 bytes of $Hash at $Offset (D4): their top 53 bits (big-endian) / 2^53
6404: # - exact in a double, so both runtimes agree to the bit.
6405: function ConvertTo-Uniform53 {
6406:     param([byte[]]$Hash, [int]$Offset = 0)
6407:     $v = [long]0
6408:     for ($i = 0; $i -lt 6; $i++) { $v = $v * 256 + [long]$Hash[$Offset + $i] }
6409:     $v = $v * 32 + ([long]$Hash[$Offset + 6] -shr 3)
6410:     return ([double]$v / 9007199254740992.0)
6411: }
